 for(let i=0;i<12;i++){let x=187+(i*73)%421,y=235+(i*43)%175;ctx.globalAlpha=.25+.2*Math.sin(t+i);ellipse(x+Math.sin(t*.8+i)*4,y,1.8,1.8,'#ffe5a5')}ctx.globalAlpha=1;glow(218,278,56,1);glow(582,275,52,2);
