 ctx.fillStyle='#c59a8a';ctx.beginPath();ctx.moveTo(-23,-30);ctx.lineTo(-20,-12);ctx.lineTo(-10,-19);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(23,-30);ctx.lineTo(20,-12);ctx.lineTo(10,-19);ctx.closePath();ctx.fill();
