const parkHostPropBefore=prop;
prop=function(id,x,y){
 if(room!=='park'||id!=='chat')return parkHostPropBefore(id,x,y);
 // Two visible hosts, grounded near a bench, no invisible conversation target.
 ctx.save();line(x-52,y-5,x-56,y+22,'#735842',5);line(x+52,y-5,x+56,y+22,'#735842',5);round(x-61,y-26,122,17,3,'#a78a62','#715940');round(x-61,y-54,122,23,2,'#9e805b','#715940');line(x-55,y-43,x+55,y-43,'#d5b38a',1.5);
 if(!drawPaintedResident({x:x-92,y:y+12,n:['Auntie Mei','梅姨']},.90,false,'right'))backHuman(x-92,y+12,1,false,'right',.87);if(!drawPaintedResident({x:x+86,y:y+12,n:['Auntie Lin','林姨']},.87,false,'left'))backHuman(x+86,y+12,3,false,'left',.87);if(talkOpen){const who=$('speaker').textContent,mei=who===tr('Auntie Mei','梅姨'),lin=who===tr('Auntie Lin','林姨');if(mei||lin){const hx=x+(mei?-92:86);ellipse(hx,y-88,14,9,'#f5e5c8');for(let j=0;j<3;j++)ellipse(hx-6+j*6,y-88+Math.sin(t*4+j)*1.2,1.4,1.4,'#82755e')}}
 const sway=Math.sin(t*2)*.10;ctx.save();ctx.translate(x+27,y-31);ctx.rotate(sway);ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(-24,-34,0,-32);ctx.quadraticCurveTo(24,-34,0,0);ctx.fillStyle='#e2caa0';ctx.fill();ctx.strokeStyle='#a28a65';ctx.stroke();ctx.restore();ctx.restore()
};
/* Fictional park serials, with saved episode, scene and player choice. */
const parkSerials=[
 {title:['The missing bench','消失的长椅'],opening:['Remember the cat who claimed the bench? Someone filed a complaint. The cat has asked for a lawyer.','还记得霸占长椅的猫吗？有人投诉了。猫现在要求请律师。'],twist:['The complainant was the park committee chair. The cat was sitting on his lunch.','投诉人是公园委员会主席。猫坐的其实是他的午饭。'],choices:[['Defend the cat','替猫辩护'],['Investigate the lunch','调查午饭']],outcomes:[['Good. We have appointed you honorary cat counsel. The legal fee is two sardines.','好，你被任命为猫咪法律顾问。律师费两条沙丁鱼。'],['Evidence recovered: one fishball, three paw prints. Case closed.','证物找到了：一颗鱼丸，三个爪印。结案。']],after:['The bench is back. The cat now has a reservation system.','长椅回来了。猫现在实行预约制。']},
 {title:['The five-minute meeting','五分钟会议'],opening:['Wang Laoban booked five minutes to discuss how to save time. We are now in hour two.','王老板约了五分钟讨论如何节省时间。现在已经开到第二个小时。'],twist:['He made a slideshow with 46 slides. The last slide says: Keep things simple.','他做了四十六页PPT。最后一页写着：化繁为简。'],choices:[['Send a fake calendar emergency','制造日历紧急事件'],['Suggest an actual break','建议真的休息']],outcomes:[['A meeting has appeared called Urgent Nap. Attendance is mandatory.','日历新增「紧急午睡会议」。全员必须参加。'],['He has formed a working group to investigate what a break is.','他成立了工作小组，研究什么叫休息。']],after:['The meeting minutes arrived. Nobody remembers attending.','会议纪要发来了。大家都不记得自己参加过。']},
 {title:['The mysterious admirer','神秘追求者'],opening:['Lin received a love note with no signature. She has been pretending not to care for three days.','林姨收到一张匿名情书。她已经假装不在乎三天了。'],twist:['It says: I think of you whenever I see a discount on kopi. Very romantic, apparently.','上面写着：每次咖啡打折，我就想到你。据说这叫浪漫。'],choices:[['Find the admirer','找出追求者'],['Leave a reply','帮忙回信']],outcomes:[['It was the kopi uncle. He was advertising a loyalty programme.','是咖啡摊老板。他在推广会员积分。'],['We wrote: Please specify the discount percentage. Romance has a budget.','我们回复：请注明折扣比例。浪漫也有预算。']],after:['Lin got a free kopi. She insists this counts as a successful date.','林姨拿到一杯免费咖啡。她坚持这算约会成功。']},
 {title:['The town council investigation','小镇调查大案'],opening:['The town council is investigating why residents look too relaxed. Naturally, we are suspects.','小镇议会正在调查居民为何看起来太悠闲。我们当然成了嫌疑人。'],twist:['Their confidential report says the main cause is sitting down.','机密报告指出：主要原因是坐下。'],choices:[['Offer the council a chair','给议会送把椅子'],['Start a relaxation committee','成立摸鱼委员会']],outcomes:[['They sat down. Investigation suspended until further notice.','他们坐下了。调查暂停，恢复时间另行通知。'],['Congratulations, you have become Chair of Chairs. No meetings allowed.','恭喜，你成了椅子委员会主席。禁止开会。']],after:['The council has classified naps as essential infrastructure.','议会把午睡列为必要基础设施。']}
];
function parkProgress(){
 const raw=load('parkSerialV1',null);if(!raw||!Number.isInteger(raw.episode)||raw.episode<0||raw.episode>=parkSerials.length||![0,1,2,3].includes(raw.beat))return {episode:0,beat:0,choice:0,day:''};
 return {...raw,choice:raw.choice===1?1:0}
}
function parkSerialTalk(){
 if(room!=='park')return;const q=parkProgress(),today=day();
 if(q.beat===3&&q.day!==today){q.episode=(q.episode+1)%parkSerials.length;q.beat=0;save('parkSerialV1',q)}
 const ep=parkSerials[q.episode],mei=['Auntie Mei','梅姨'],lin=['Auntie Lin','林姨'];
 const leave=[tr('Continue later','下次接着聊'),closeTalk];
 const next=(beat,choice=q.choice)=>{save('parkSerialV1',{...q,beat,choice,day:beat===3?today:q.day});if(beat===3){lifeFriend(mei);lifeFriend(lin)}parkSerialTalk()};
 if(q.beat===0)say(tr(...mei),tr(...ep.opening),[[tr('Wait, what happened?','等等，怎么回事？'),()=>next(1)],leave]);
 else if(q.beat===1)say(tr(...lin),tr(...ep.twist),[...ep.choices.map((v,i)=>[tr(...v),()=>next(2,i)]),leave]);
 else if(q.beat===2)say(tr(...mei),tr(...ep.outcomes[q.choice]),[[tr('And then?','然后呢？'),()=>next(3)],leave]);
 else say(tr(...lin),tr(...ep.after)+' '+tr('Come back another day. Mei always knows something.','改天再来，梅姨总有新瓜。'),[[tr('Remind me what happened','回顾刚才的瓜'),()=>say(tr(...mei),tr(...ep.outcomes[q.choice]),[[tr('See you tomorrow','明天见'),closeTalk]])],[tr('See you around','回头见'),closeTalk]])
}
const parkGossipAction=action;
action=function(id){
 if(room==='park'&&id==='chat'){closeTalk();parkSerialTalk();return}
 return parkGossipAction(id)
};

/* Choose symbolic frustrations, not named human targets. All text stays local;
   no free-text personal names or public accusations. */
function stressReplyPool(index){
 let offset=0;for(const group of stressGroups){if(index>=offset&&index<offset+group.targets.length)return group.replies;offset+=group.targets.length}return auntieHitReplies
}
function chooseStressTarget(index){
 if(!Number.isInteger(index)||index<0||index>=stressTargets.length)return false;
 stressTarget=index;stressCombo=0;stressPieces=[];stressSwingAt=-10;
 $('page').style.display='none';
 hint('Ah Ma: Give this one a good whack!','阿嬷：来，这个给我狠狠打！');return true
}
function openStressChoices(){
 if(activity!=='hit')return;
 page(tr('What is getting on your nerves?','今天想打走什么烦恼？'),tr('Choose the frustration, not a real person. Ah Ma has a slipper for everything.','不打真人，只打烦恼。阿嬷的拖鞋专治各种不顺。'),q=>{
  const wrap=element('div','',q,'stressChoiceBook');let offset=0;
  for(const group of stressGroups){const section=element('section','',wrap,'stressChoiceSection');element('h2',tr(...group.label),section);const grid=element('div','',section,'stressChoiceGrid');for(const [j,v] of group.targets.entries()){const index=offset+j,btn=b(grid,tr(...v),()=>chooseStressTarget(index));btn.setAttribute('aria-pressed',String(index===stressTarget))}offset+=group.targets.length}
  b(wrap,tr('Surprise me','随机挑一个'),()=>{const n=stressTargets.length;chooseStressTarget((stressTarget+1+Math.floor(Math.random()*(n-1)))%n)})
 })
}
const stressChoiceStyle=document.createElement('style');stressChoiceStyle.textContent='.stressChoiceBook{max-width:560px;margin:auto}.stressChoiceSection{padding:12px 0;border-bottom:1px solid #b99e74}.stressChoiceSection h2{font-size:18px;margin:0 0 10px}.stressChoiceGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.stressChoiceGrid button{min-height:44px;white-space:normal;line-height:1.3;padding:8px;font-size:14px}.stressChoiceGrid button[aria-pressed=true]{background:#52674f;color:#fff3d8}.stressChoiceBook>button{min-height:44px;margin-top:12px;width:100%}';document.head.append(stressChoiceStyle);

/* Petty paper curses: original, harmless everyday inconveniences. One per valid hit,
   without actual threats, real names, or changing the rewards. */
const pettyPaperCurses=[["May every public toilet you enter be out of paper.","祝你每次上公厕，厕纸刚好用完。"],["May your phone charger work only at a very specific angle.","祝你充电线只有扭成麻花才充得进电。"],["May your bubble tea straw miss every pearl.","祝你喝奶茶，一颗珍珠都吸不到。"],["May your trousers feel tight immediately after lunch.","祝你午饭刚吃完，裤头就开始抗议。"],["May your socks always slide down inside your shoes.","祝你的袜子走两步就滑进鞋里。"],["May your boss's slides have the wrong font on every page.","祝老板的PPT每一页都字体错乱。"],["May your meeting room booking disappear just as the meeting starts.","祝你会议刚开始，会议室就被别人订了。"],["May your favourite snack contain ninety percent air.","祝你买的薯片，九成都是空气。"],["May your noodles come with a fork that bends.","祝你吃面的时候，叉子一用就弯。"],["May your lift stop on every floor.","祝你搭电梯，层层都停。"],["May your online delivery arrive just after you leave.","祝你刚出门，快递就到了。"],["May your umbrella turn inside out on a sunny day.","祝你撑伞没下雨，伞还自己翻了。"],["May your coffee always be lukewarm.","祝你喝热咖啡不够热，喝冰咖啡不够冰。"],["May your Wi-Fi disconnect at ninety-nine percent.","祝你下载到百分之九十九，网络断了。"],["May the last piece of toilet paper tear diagonally.","祝你最后一格厕纸，一撕就裂成三角形。"],["May your favourite pen run out halfway through your signature.","祝你签名签到一半，笔没墨了。"],["May every queue you switch to become the slow one.","祝你每次换队，换完原来的队就快了。"],["May your takeaway sauce be on the other side of the bag.","祝你外卖酱料藏在袋子最底下。"],["May the last dumpling always belong to someone else.","祝你想吃最后一个饺子，别人已经夹走了。"],["May your printer demand magenta to print a black page.","祝你打印黑白文件，打印机偏偏说缺红墨。"],["May autocorrect turn your serious email into nonsense.","祝你发严肃邮件，自动纠错比你还会加戏。"],["May your earbuds always end up in the wrong pocket.","祝你找耳机，永远先摸错口袋。"],["May your rice cooker finish just when you have to leave.","祝你饭刚煮好，人就得出门。"],["May your shopping cart have that one squeaky wheel.","祝你每次推购物车，都碰上那个吱吱叫的轮子。"],["May your alarm go off during your day off.","祝你休假那天，闹钟忘了关。"],["May your toast land jam-side down.","祝你面包掉地上，永远是果酱那一面。"],["May the aircon remote always be just out of reach.","祝你躺下才发现空调遥控器在另一头。"],["May your bank app log out just as you need to pay.","祝你付款的时候，银行App突然要求重新登录。"],["May your food delivery say 'arriving soon' for twenty minutes.","祝你外卖的马上到，永远还有二十分钟。"],["May your perfectly folded laundry unfold itself.","祝你叠好的衣服，拿一件倒一摞。"],["May your calendar invite have no meeting link.","祝你开线上会，邀请里偏偏没链接。"],["May your ice cream cone drip before you find a tissue.","祝你纸巾还没找到，冰淇淋先滴下来。"],["May every vending machine reject your perfectly good coin.","祝你投个完好无损的硬币，机器偏不认。"],["May your video buffer at the punchline.","祝你看视频，笑点前一秒卡住。"],["May your favourite seat always be occupied by a very comfortable cat.","祝你最爱的座位，永远被一只睡熟的猫霸占。"],["May your keyboard space bar squeak during a quiet meeting.","祝你开会全场安静时，空格键吱吱响。"]];
const activityComedy={"clawMiss":[["The claw caught a whole lot of absolutely nothing.","恭喜你，成功夹到了空气。"],["That plush has better escape skills than my colleagues at 6pm.","这玩偶下班逃跑的速度，比我同事还快。"],["The machine would like to thank you for your imaginary donation.","机器感谢你的空气捐款。"],["The claw is doing the bare minimum. Relatable.","夹爪正在消极怠工，懂了。"],["The plush just dodged another responsibility.","玩偶又成功逃避了一项责任。"]],"clawWin":[["Congratulations. Your new colleague has never sent an email.","恭喜，新同事不会发邮件。"],["Finally, a colleague who sits quietly.","终于有个安静的同事了。"],["The plush has accepted your offer. No probation required.","玩偶已接受录用，不用试用期。"]],"soup":[["Grandma: Good. At least you didn't put your annual leave in the soup.","外婆：不错，至少没把年假煮进去。"],["Grandma: This soup is better than your boss's promises.","外婆：这碗汤比老板画的饼实在。"],["Grandma: Eat first. You can't survive on air and complaints.","外婆：先吃饭，光靠怨气和空气可活不了。"],["Grandma: Not bad. I can retire for five minutes.","外婆：还行，我可以退休五分钟。"],["Grandma: A bowl of soup, not a status report. Stop analysing it.","外婆：喝个汤，又不是写汇报，别分析了。"]],"tea":[["Finally, a deadline you can drink.","终于有个能喝下去的截止日期。"],["The pearls are working harder than the management.","珍珠比管理层还努力。"],["A drink this good deserves its own public holiday.","好喝到应该为它设个公共假期。"],["The boss may control your calendar, not your sugar level.","老板管得了日历，管不了几分糖。"]],"rhythmHigh":[["Your dance moves have been approved. Unlike your leave.","舞步审批通过，年假还是没有。"],["HR would like to know where you learned those moves.","人事部想知道你从哪儿学的舞步。"]],"rhythmLow":[["Your feet have submitted conflicting reports.","你的两只脚提交了互相矛盾的报告。"],["The dance floor survived. So did you.","舞池没事，你也没事，算赢。"],["Rhythm is temporarily out of office.","节奏感暂时不在办公室。"]],"box":[["This tiny creature has zero professional qualifications and excellent vibes.","这个小家伙毫无职业资质，但情绪价值满分。"],["A new resident with no rent, no deadlines and no CV.","新居民：不用交房租，不用赶工，也没有简历。"],["Plot twist: your toy is better rested than you.","剧情反转：玩偶休息得比你好。"]]};
const pettyHitBefore=smack;
smack=function(){
 if(activity!=='hit'||$('page').style.display==='block')return;
 const count=state.count;pettyHitBefore();if(state.count===count)return;
 const curse=townReaction('petty-paper-curses',pettyPaperCurses);
 // The persistent hint is always a new curse, even on milestone hits.
 hint('Ah Ma: '+curse[0],'阿嬷：'+curse[1])
};
const comedyClawBefore=clawFinish;
clawFinish=function(){const active=state.dropping;comedyClawBefore();if(active&&state.clawResult){const win=state.clawResult.i>=0;hint(...townReaction(win?'claw-comedy-win':state.clawStreak>=3?'claw-comedy-repeat':'claw-comedy-miss',win?activityComedy.clawWin:state.clawStreak>=3?clawRepeatRoasts:activityComedy.clawMiss))}};
const comedyRhythmBefore=rhythmFinish;
rhythmFinish=function(){const active=state.rhythmStage==='play';comedyRhythmBefore();if(active){const high=state.rhythmScore>=1600;hint(...townReaction(high?'rhythm-comedy-high':'rhythm-comedy-low',high?activityComedy.rhythmHigh:activityComedy.rhythmLow))}};
const comedyBoxBefore=boxAward;
boxAward=function(){const active=state.boxStage==='opening';comedyBoxBefore();if(active&&state.boxStage==='result')hint(...townReaction('box-comedy',activityComedy.box))};

