/* Shared screen-space layout contract for plaques and nearby name tags.
   Rectangles include touch padding. Unsafe placements are omitted, not stacked. */
function meowPlaceText(cx,cy,w,h,bounds,blockers,maxShift=40){
 if(![cx,cy,w,h,maxShift,bounds.left,bounds.top,bounds.right,bounds.bottom].every(Number.isFinite)||w<=0||h<=0||bounds.right-bounds.left<w+8||bounds.bottom-bounds.top<h+8)return null;
 const pad=4,loX=bounds.left+w/2+pad,hiX=bounds.right-w/2-pad,loY=bounds.top+h/2+pad,hiY=bounds.bottom-h/2-pad;
 const options=[],seen=new Set();
 for(const dy of [0,-h/2-6,h/2+6,-h-8,h+8,-maxShift,maxShift])for(const dx of [0,-w/3,w/3,-maxShift,maxShift]){
  const x=clamp(cx+dx,loX,hiX),y=clamp(cy+dy,loY,hiY);
  if(Math.hypot(x-cx,y-cy)>maxShift+.01)continue;
  const key=Math.round(x*10)+':'+Math.round(y*10);if(seen.has(key))continue;seen.add(key);
  const rect={left:x-w/2-pad,right:x+w/2+pad,top:y-h/2-pad,bottom:y+h/2+pad};
  if(blockers.some(b=>b&&rect.left<b.right&&rect.right>b.left&&rect.top<b.bottom&&rect.bottom>b.top))continue;
  options.push({x,y,rect,score:Math.abs(x-cx)*1.4+Math.abs(y-cy)})
 }
 return options.sort((a,b)=>a.score-b.score)[0]||null
}
let meowTextFrameRects=[],meowFrameBlockers=[],meowUIRects=[],meowUILast=-Infinity;
function meowVisibleRects(selector){
 const root=$('game').getBoundingClientRect(),out=[];
 for(const el of document.querySelectorAll(selector)){
  if(el.hidden||!el.getClientRects().length)continue;
  const style=getComputedStyle(el),b=el.getBoundingClientRect();
  if(style.visibility==='hidden'||style.display==='none'||Number(style.opacity)===0||!b.width||!b.height)continue;
  out.push({left:b.left-root.left-4,right:b.right-root.left+4,top:b.top-root.top-4,bottom:b.bottom-root.top+4})
 }
 return out
}
function meowIndoorActorBounds(a,scale=travellerRoomScale(H,cam.scale)){
 const x=cam.ox+a.x*cam.scale,y=cam.oy+a.y*cam.scale,h=94*scale*cam.scale,w=Math.max(30,h*.7);
 return {left:x-w/2-5,right:x+w/2+5,top:y-h-5,bottom:y+6}
}
function meowBeginTextFrame(inside){
 meowTextFrameRects=[];
 const now=performance.now();
 if(now-meowUILast>100){meowUILast=now;meowUIRects=meowVisibleRects('#hud>*,#small button,#dock,#back,#hint,#gameControls,#movePad,#moveGuide,#walkHelp,#ritualActionBar,#pearlRecipePanel,#dialogue,#nextStopShortcut,#lunarRibbon,#destinyAccess,#wonderQuestionSheet,#storyReadingSheet,#cafeQuestionSheet,#threeBoardAccess')}
 meowFrameBlockers=[...meowUIRects];
 if(inside){
  if(continuityRoom===room)meowFrameBlockers.push(meowIndoorActorBounds(indoor));
  for(const actor of roomResidentActors())meowFrameBlockers.push(meowIndoorActorBounds(actor,actor.sc));
  for(const a of sharedTownActors())meowFrameBlockers.push(meowIndoorActorBounds(a));
 }else{
  for(const a of [p,...npc,...sharedTownActors()])meowFrameBlockers.push(characterScreenBounds(a,a===p));
  // Actual visible signs take precedence over actor names; reserve their current rectangles.
  meowFrameBlockers.push(...meowVisibleRects('#worldSigns .worldSign'));
  for(const [id,x,y] of maps[scene].st){
   const [ax,ay]=housePlaqueAnchor(scene,id,x,y),sx=cam.ox+ax*cam.scale,sy=cam.oy+ay*cam.scale;
   meowFrameBlockers.push({left:sx-70,right:sx+70,top:sy-26,bottom:sy+26})
  }
 }
}
/* Passersby get a readable, gently fading label instead of a frame-by-frame nearest-name swap. */
const meowPasserLabels=new WeakMap();
function meowPasserOpacity(a){
 const dist=Math.hypot(a.x-p.x,a.y-p.y),now=performance.now();let q=meowPasserLabels.get(a);
 if(!q||q.scene!==scene||now-q.last>1000){q={scene,inside:false,entered:now,shown:-Infinity,alpha:0,last:now};meowPasserLabels.set(a,q)}
 const dt=Math.min(80,Math.max(0,now-q.last));q.last=now;
 const approach=a.popGuest?200:145,depart=a.popGuest?245:185;
 if(!q.inside&&dist<approach){q.inside=true;q.entered=now}
 else if(q.inside&&dist>depart)q.inside=false;
 const wants=q.inside&&now-q.entered>=220;
 if(wants&&q.alpha===0)q.shown=now;
 const hold=dist<235&&q.alpha>0&&now-q.shown<1250;
 q.alpha=clamp(q.alpha+(wants||hold?dt/230:-dt/380),0,1);
 return q.alpha;
}
function drawMeowActorName(a,value,indoorScale=null){
 if(talkOpen||!value)return;
 const alpha=indoorScale===null?meowPasserOpacity(a):1;if(alpha<=.01)return;
 const bounds=indoorScale===null?characterScreenBounds(a):meowIndoorActorBounds(a,indoorScale),scale=Math.max(.08,cam.scale),size=12/scale;
 ctx.save();try{
  ctx.font='600 '+size+'px Georgia, "Songti SC", serif';
  let name=String(value),max=Math.min(176,W*.48),w=ctx.measureText(name).width*scale+14;
  if(w>max){const chars=Array.from(name);while(chars.length>1&&ctx.measureText(chars.join('')+'…').width*scale+14>max)chars.pop();name=chars.join('')+'…';w=ctx.measureText(name).width*scale+14}
  const h=24,cx=(bounds.left+bounds.right)/2,cy=bounds.top-h/2-9,blockers=[...meowFrameBlockers,bounds,...meowTextFrameRects],q=indoorScale===null?meowPasserLabels.get(a):null;
  let spot=null;
  if(q?.offset){const x=cx+q.offset.x,y=cy+q.offset.y,rect={left:x-w/2,right:x+w/2,top:y-h/2,bottom:y+h/2};if(rect.left>=5&&rect.right<=W-5&&rect.top>=5&&rect.bottom<=H-5&&!blockers.some(b=>speechOverlap(rect,b)))spot={x,y,rect}}
  if(!spot)spot=meowPlaceText(cx,cy,w,h,{left:5,right:W-5,top:5,bottom:H-5},blockers,25);
  if(!spot){if(q)q.blockedAt=performance.now();return}if(q){q.offset={x:spot.x-cx,y:spot.y-cy};if(q.blockedAt&&performance.now()-q.blockedAt<160)return;if(q.blockedAt){q.reappearAt=performance.now();q.blockedAt=0}}meowTextFrameRects.push(spot.rect);ctx.globalAlpha*=alpha*(q?.reappearAt?clamp((performance.now()-q.reappearAt)/220,0,1):1);
  const x=(spot.x-cam.ox)/scale,y=(spot.y-cam.oy)/scale;
  round(x-w/scale/2,y-h/scale/2,w/scale,h/scale,4/scale,a.popGuest?'#f7e6b9ed':'#f6e8cdeb',a.popGuest?'#b78c46':'#aa9672');ctx.font='600 '+size+'px Georgia, "Songti SC", serif';ctx.fillStyle=a.popGuest?'#77562d':'#425646';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(name,x,y)
 }finally{ctx.restore()}
}
